<script setup lang="ts">
import {computed,ref} from 'vue';import {usePlatform} from '../stores/platform';import {filterRows,localTime} from '../domain';import type {Capture} from '../domain';import QueryForm from '../components/QueryForm.vue';import DataTable from '../components/DataTable.vue';import {apiMode} from '../api/client';
const p=usePlatform(),tab=ref('详情'),watch=computed(()=>p.db.watches.find(w=>w.id===p.detail?.id)),rows=computed(()=>p.filterRows(p.db.watches,p.f,{name:r=>r.name,account:r=>r.account,start:r=>r.start,end:r=>r.end}));
const remoteAlerts=computed(()=>p.remote.alerts.map(alert=>({id:alert.alertId,watchName:p.remote.watches[alert.ruleId]?.name||alert.ruleId,target:p.remote.captures[alert.captureId]?.displayTarget||alert.target.targetId,targetId:alert.target.targetId,targetType:alert.target.targetType,time:localTime(alert.occurredAt),site:p.db.sites.find(site=>site.id===alert.siteId)?.name||alert.siteId||'',device:p.db.devices.find(device=>device.id===alert.deviceId)?.name||alert.deviceId||'',status:alert.status})));
const hits=computed(()=>apiMode==='http'?remoteAlerts.value:p.captureRows().filter(c=>watch.value?.hits.includes(c.id)));
const stats=computed(()=>apiMode==='http'?p.remote.watchStatistics?.items.map(item=>({id:item.target.targetId,target:item.displayTarget,count:item.captureCount,stations:item.siteCount,regions:item.regionCount,first:item.firstSeenAt?localTime(item.firstSeenAt):'',captures:[] as Capture[]}))||[]:p.statistics(hits.value as Capture[],hits.value as Capture[]));
const alerts=computed<Record<string,unknown>[]>(()=>apiMode==='http'?remoteAlerts.value:p.db.watches.flatMap(w=>p.captureRows().filter(c=>w.hits.includes(c.id)).map(c=>({...c,watchName:w.name,status:w.status}))));
</script>
<template><template v-if="p.active==='告警结果'"><QueryForm :model="p.f" :fields="[{key:'name',label:'布控任务名称'},{key:'start',label:'告警开始',type:'datetime-local'},{key:'end',label:'告警结束',type:'datetime-local'}]" @search="p.query" @reset="p.reset"/><DataTable :rows="p.filterRows(alerts,p.f,{name:r=>r.watchName,start:r=>r.time,end:r=>r.time})" :columns="[{key:'watchName',label:'布控任务'},{key:'target',label:'命中目标'},{key:'time',label:'采集时间'},{key:'site',label:'场所'},{key:'status',label:'状态'}]"><template v-if="apiMode==='mock'" #rowActions="{row}"><el-button link type="primary" @click="p.dataAction('检索',[row as Capture])">检索</el-button><el-button link type="primary" @click="p.dataAction('伴随',[row as Capture])">伴随</el-button></template></DataTable></template><template v-else-if="watch"><section class="card"><div class="section-head"><h3>{{watch.name}}</h3><el-button @click="p.formWatch(watch.id)">编辑信息</el-button><el-tag>{{watch.status}}</el-tag></div><dl><dt>目标</dt><dd>{{watch.target}}</dd><dt>布控账号</dt><dd>{{watch.account}}</dd><dt>布控时间</dt><dd>{{watch.start}} 至 {{watch.end}}</dd><dt>通知方式与对象</dt><dd>{{watch.channel}} · {{watch.recipient}}</dd></dl><div v-if="apiMode==='mock'" class="actions"><el-button :disabled="watch.status!=='运行中'" @click="p.simulateWatch(watch.id)">模拟命中</el-button><el-button :disabled="watch.status!=='运行中'" @click="p.simulateWatch(watch.id,true)">模拟任务结束</el-button></div><div class="watch-tabs" role="tablist" aria-label="布控详情视图"><button role="tab" :aria-selected="tab==='详情'" @click="tab='详情'">详情</button><button role="tab" :aria-selected="tab==='统计'" :aria-disabled="watch.status!=='已结束'" :disabled="watch.status!=='已结束'" @click="tab='统计'">统计</button></div><el-alert v-if="watch.status!=='已结束'" title="统计数据在布控任务结束后生成" type="info" :closable="false"/></section><DataTable v-if="tab==='详情'" :rows="hits" :columns="[{key:'target',label:'目标'},{key:'time',label:'采集时间'},{key:'site',label:'场所'},{key:'device',label:'设备'}]"><template v-if="apiMode==='mock'" #rowActions="{row}"><el-button v-for="a in ['检索','伴随']" :key="a" link type="primary" @click="p.dataAction(a,[row as Capture])">{{a}}</el-button></template></DataTable><DataTable v-else :rows="stats" :columns="[{key:'target',label:'目标'},{key:'count',label:'勘测总次数'},{key:'stations',label:'经过站点数量'},{key:'regions',label:'经过区域数量'},{key:'first',label:'最早出现时间'}]"><template v-if="apiMode==='mock'" #rowActions="{row}"><el-button v-for="a in ['检索','伴随','轨迹','布控']" :key="a" link type="primary" @click="p.dataAction(a,row.captures as Capture[])">{{a}}</el-button></template></DataTable></template><template v-else><QueryForm :model="p.f" :fields="[{key:'name',label:'布控名称'},{key:'account',label:'布控账号'},{key:'start',label:'布控开始',type:'datetime-local'},{key:'end',label:'布控结束',type:'datetime-local'}]" label="查询" @search="p.query" @reset="p.reset"/><div class="actions"><el-button type="primary" @click="p.formWatch()">新增</el-button><el-button @click="p.remove('watches')">删除</el-button></div><DataTable :rows="rows" :columns="[{key:'name',label:'布控名称',link:true},{key:'account',label:'布控账号'},{key:'start',label:'布控开始'},{key:'end',label:'布控结束'},{key:'type',label:'数据类型'},{key:'status',label:'状态'}]" title="布控任务" @select="p.chosen=$event" @open="row=>{tab='详情';p.openDetail('watch',String(row.id))}"/><div class="actions"><el-button @click="p.revoke('watches')">撤销布控</el-button></div></template></template>



<style scoped>
.watch-tabs{display:flex;gap:24px;border-bottom:2px solid var(--el-border-color-light);margin:16px 0}.watch-tabs button{border:0;border-bottom:2px solid transparent;padding:12px 4px;background:transparent;cursor:pointer;font:inherit;color:var(--el-text-color-primary)}.watch-tabs button[aria-selected="true"]{border-bottom-color:var(--el-color-primary);color:var(--el-color-primary)}.watch-tabs button:disabled{color:var(--el-text-color-disabled);cursor:not-allowed}
</style>
